 "content": "def transform(grid):
    g = [row[:] for row in grid]
    h, w = len(g), len(g[0])
    # Divider lines are full rows/columns of color 4; copy the non-background
    # pattern from its panel into every other equally sized panel.
    bg = next((v for row in g for v in row if v not in (4,)), 0)
    row_bands = []
    start = 0
    for r in range(h):
        if all(v == 4 for v in g[r]):
            if start < r: row_bands.append((start, r))
            start = r + 1
    if start < h: row_bands.append((start, h))
    col_bands = []
    start = 0
    for c in range(w):
        if all(g[r][c] == 4 for r in range(h)):
            if start < c: col_bands.append((start, c))
            start = c + 1
    if start < w: col_bands.append((start, w))
    source = None
    for ri, (r0, r1) in enumerate(row_bands):
        for ci, (c0, c1) in enumerate(col_bands):
            if any(g[r][c] != bg for r in range(r0, r1) for c in range(c0, c1)):
                source = (ri, ci)
                break
        if source: break
    if source is None: return g
    sr0, sr1 = row_bands[source[0]]
    sc0, sc1 = col_bands[source[1]]
    pattern = [[g[r][c] for c in range(sc0, sc1)] for r in range(sr0, sr1)]
    for ri, (r0, r1) in enumerate(row_bands):
        for ci, (c0, c1) in enumerate(col_bands):
            if (r1-r0, c1-c0) != (len(pattern), len(pattern[0])): continue
            for dr in range(r1-r0):
                for dc in range(c1-c0):
                    g[r0+dr][c0+dc] = pattern[dr][dc]
    return g
